async fn scope_masked_criteria_is_denied_before_evaluation() {
    let (_dir, store, version, principal) = setup().await;
    let service = ActionService::new(
        &store,
        ActionLimits::new(8, 8, 65536).expect("limits"),
        tokens(),
    );
    let outcome = service
        .execute(
            &principal,
            &scope(true, false),
            version,
            request("A1", "masked"),
        )
        .await;
    assert!(
        matches!(outcome, Err(ActionError::ScopeDenied)),
        "masked criterion must be denied, not evaluated: {outcome:?}"
    );
}

async fn scope_write_column_must_be_visible() {
    let defs = DEFS.replace(
        "objects.gate.name == \"Allowed\"",
        "params.name == \"Updated\"",
    );
    let (_dir, store, version, principal) = setup_with_defs(&defs).await;
    let service = ActionService::new(
        &store,
        ActionLimits::new(8, 8, 65536).expect("limits"),
        tokens(),
    );
    let result = service
        .execute(
            &principal,
            &scope(true, false),
            version,
            request("A1", "write-masked"),
        )
        .await;
    assert!(
        matches!(result, Err(ActionError::ScopeDenied)),
        "masked write must fail: {result:?}"
    );
    assert_eq!(store.read_log(0, 10).await.expect("log").len(), 1);
}

async fn scope_post_state_must_remain_visible() {
    let (_dir, store, version, principal) = setup().await;
    let mut granted = scope(true, true);
    granted.types.get_mut("Gate").expect("type scope").row = Pred::Cmp {
        left: Operand::Column("name".to_owned().try_into().expect("name")),
        op: CmpOp::Eq,
        right: Operand::Lit(Scalar::String("Allowed".to_owned())),
    };
    let service = ActionService::new(
        &store,
        ActionLimits::new(8, 8, 65536).expect("limits"),
        tokens(),
    );
    let result = service
        .execute(
            &principal,
            &granted,
            version,
            request("A1", "post-invisible"),
        )
        .await;
    assert!(matches!(result, Err(ActionError::ScopeDenied)));
    assert_eq!(store.read_log(0, 10).await.expect("log").len(), 1);
}

async fn scope_link_requires_both_endpoints() {
    let defs = format!(
        "{DEFS}---\nkind: ObjectType\napiName: Pilot\nbacking: editOnly\nprimaryKey: code\nproperties:\n  code: {{ type: string, required: true }}\n  name: {{ type: string, required: true }}\n---\nkind: LinkType\napiName: gateCrew\ncardinality: manyToMany\nfrom: {{ objectType: Gate, apiName: crew }}\nto: {{ objectType: Pilot, apiName: gates }}\nbacking: editOnly\n---\nkind: ActionType\napiName: connectCrew\nparameters:\n  gate: {{ type: {{ objectReference: Gate }}, required: true }}\n  pilot: {{ type: {{ objectReference: Pilot }}, required: true }}\nrules:\n  - kind: addLink\n    link: gateCrew\n    from: gate\n    to: pilot\n"
    );
    let (_dir, store, version, principal) = setup_with_defs(&defs).await;
    store
        .commit(Commit {
            actor: Actor::Principal(principal.id.as_str().to_owned()),
            action: "seed".to_owned(),
            def_version: version,
            params: serde_json::Value::Null,
            edits: vec![Edit::Object {
                type_name: "Pilot".to_owned().try_into().expect("type"),
                pk: PropertyValue::String("P1".to_owned()),
                op: ObjectOp::Set(BTreeMap::from([(
                    "name".to_owned().try_into().expect("name"),
                    PropertyValue::String("Pilot".to_owned()),
                )])),
            }],
        })
        .await
        .expect("seed pilot");
    let mut granted = scope(true, true);
    granted
        .actions
        .insert("connectCrew".to_owned().try_into().expect("action"));
    granted.types.insert(
        "Pilot".to_owned().try_into().expect("type"),
        TypeScope {
            row: Pred::Const(true),
            columns: ["code", "name"]
                .into_iter()
                .map(|name| {
                    (
                        name.to_owned().try_into().expect("column"),
                        Pred::Const(true),
                    )
                })
                .collect(),
        },
    );
    let request = |pilot: &str, validate_only: bool| ActionRequest {
        action: "connectCrew".to_owned(),
        command_id: (!validate_only).then(|| "link".to_owned()),
        items: vec![ActionItem {
            params: serde_json::from_value(serde_json::json!({
                "gate": "A1", "pilot": pilot,
            }))
            .expect("params"),
            expected_versions: BTreeMap::new(),
        }],
        validate_only,
    };
    let service = ActionService::new(
        &store,
        ActionLimits::new(8, 8, 65536).expect("limits"),
        tokens(),
    );
    let mut hidden_from = granted.clone();
    hidden_from.types.get_mut("Gate").expect("Gate").row = Pred::Const(false);
    let mut hidden_to = granted.clone();
    hidden_to.types.get_mut("Pilot").expect("Pilot").row = Pred::Const(false);
    for (permission, request) in [
        (&hidden_from, request("P1", false)),
        (&hidden_to, request("P1", true)),
        (&granted, request("P2", true)),
    ] {
        let result = service
            .execute(&principal, permission, version, request)
            .await;
        assert!(
            matches!(result, Err(ActionError::ScopeDenied)),
            "hidden/missing link endpoint: {result:?}"
        );
    }
    assert_eq!(store.read_log(0, 10).await.expect("log").len(), 2);
}

async fn release_source_visibility_guard() {
    let defs = format!(
        "{DEFS}---\nkind: ActionType\napiName: releaseGate\nparameters:\n  gate: {{ type: {{ objectReference: Gate }}, required: true }}\nrules:\n  - kind: releaseObject\n    object: gate\n"
    );
    let f = fixture_with_defs(true, &defs).await;
    let request = |id: &str, validate_only: bool| ActionRequest {
        action: "releaseGate".to_owned(),
        command_id: Some(id.to_owned()),
        items: vec![ActionItem {
            params: serde_json::from_value(serde_json::json!({"gate":"G1"})).expect("params"),
            expected_versions: BTreeMap::new(),
        }],
        validate_only,
    };
    let hidden = CountingEngine::rows(vec![vec![
        EngineValue::String("G1".to_owned()),
        EngineValue::String("Old".to_owned()),
        EngineValue::Null,
    ]]);
    for (id, validate_only) in [("hidden", false), ("dry-hidden", true)] {
        let error = ActionService::new(&f.store, limits(), &f.tokens)
            .with_engine(&hidden)
            .execute(
                &f.principal,
                &f.scope,
                f.version,
                request(id, validate_only),
            )
            .await
            .expect_err("release must verify source post-state visibility");
        assert!(matches!(error, ActionError::ScopeDenied), "{error:?}");
        assert!(
            f.store
                .action_command(f.principal.id.as_str(), id)
                .await
                .expect("command")
                .is_none()
        );
    }
    assert_eq!(f.store.read_log(0, 10).await.expect("log").len(), 1);
    let visible = CountingEngine::rows(vec![source_row("open")]);
    let result = ActionService::new(&f.store, limits(), &f.tokens)
        .with_engine(&visible)
        .execute(&f.principal, &f.scope, f.version, request("release", false))
        .await
        .expect("visible source can be released");
    assert!(matches!(result, ActionOutcome::Committed(_)));
    let active = f.store.active_definition().await.expect("active");
    let edit = f
        .store
        .read_object_edit(
            &active,
            &"Gate".to_owned().try_into().expect("type"),
            &PropertyValue::String("G1".to_owned()),
        )
        .await
        .expect("edit read")
        .expect("edit row");
    assert!(edit.row.released);
    assert_eq!(f.store.read_log(0, 10).await.expect("log").len(), 2);
}

async fn source_guard_absent_target_insert_race() {
    let pg = support::pg_store().await;
    let loaded = load_from_memory(&[
        ("ontology.yaml", "apiName: demo\ndefaultProfile: dev\n"),
        ("defs.yaml", DEFS),
        ("bindings/dev/gate.yaml", BINDING),
    ]);
    assert!(loaded.diagnostics.is_empty(), "{:?}", loaded.diagnostics);
    let version = reload(
        &pg.store,
        &loaded.ontology.expect("ontology"),
        &ReloadOptions::default(),
    )
    .await
    .expect("reload")
    .def_version
    .expect("version");
    let auth = fixture(true).await;
    let other = pg.open_another(Duration::from_secs(5)).await;
    let engine = CountingEngine::rows(vec![source_row("open")]);
    let error = Box::pin(
        ActionService::new(&pg.store, limits(), &auth.tokens)
            .with_engine(&engine)
            .execute_with_test_gate(
                &auth.principal,
                &auth.scope,
                version,
                request("raced"),
                async {
                    other
                        .commit(Commit {
                            actor: Actor::Principal("test|concurrent".to_owned()),
                            action: "concurrent".to_owned(),
                            def_version: version,
                            params: serde_json::json!({}),
                            edits: vec![Edit::Object {
                                type_name: "Gate".to_owned().try_into().expect("type"),
                                pk: PropertyValue::String("G1".to_owned()),
                                op: ObjectOp::Set(BTreeMap::from([(
                                    "name".to_owned().try_into().expect("property"),
                                    PropertyValue::String("Concurrent".to_owned()),
                                )])),
                            }],
                        })
                        .await
                        .expect("independent insert");
                },
            ),
    )
    .await
    .expect_err("lock guard must reject inserted edit row");
    assert!(matches!(error, ActionError::VersionConflict), "{error:?}");
    assert_eq!(engine.calls(), 1);
    assert_eq!(pg.store.read_log(0, 10).await.expect("log").len(), 1);
    assert!(
        pg.store
            .action_command(auth.principal.id.as_str(), "raced")
            .await
            .expect("command")
            .is_none()
    );
    let outbox: i64 = sqlx::query_scalar(sqlx::AssertSqlSafe(format!(
        "SELECT count(*) FROM \"{}\".of_webhook_outbox",
        pg.schema_sys
    )))
    .fetch_one(pg.side())
    .await
    .expect("outbox count");
    assert_eq!(outbox, 0);
}

