        .and(body_string_contains("SELECT nationkey FROM demo.tiny.nation"))
        .respond_with(move |_: &wiremock::Request| {
            signal.notify_one();
            waiting.lock().unwrap().recv_timeout(Duration::from_secs(10)).expect("release in-flight L2 response");
            ResponseTemplate::new(200).set_body_json(json!({"id":"read", "columns":[{"name":"nationkey","type":"integer"}], "data":[[1]], "stats":{"state":"FINISHED"}}))
        })
        .with_priority(1)
        .mount(&server).await;

    let store = Arc::new(store);
    let engine = Arc::new(engine);
    let config = Arc::new(config);
    let worker = {
        let store = Arc::clone(&store);
        let engine = Arc::clone(&engine);
        let config = Arc::clone(&config);
        let principal = principal.clone();
        let scope = scope.clone();
        let first = Arc::clone(&first);
        tokio::spawn(async move {
            L2Service {
                principal: &principal,
                scope: &scope,
                active: first,
                engine: &engine,
                store: &store,
                config: &config,
            }
            .execute_query("SELECT nationkey FROM demo.tiny.nation")
            .await
        })
    };
    tokio::time::timeout(Duration::from_secs(3), started.notified())
        .await
        .unwrap();
    assert!(!worker.is_finished(), "source response is still blocked");
    let empty = ScopeSet::default();
    let empty_plan = store.scope_plan(&empty, &BTreeMap::new()).await.unwrap();
    store
        .scope_apply(&empty, &BTreeMap::new(), &empty_plan.hash, "test@host")
        .await
        .unwrap();
    let mut changed = ontology;
    changed.description = Some("L2 snapshot version two".to_owned());
    reload(&store, &changed, &ReloadOptions::default())
        .await
        .unwrap();
    let second = store.active_definition().await.unwrap();
    assert_eq!(second.def_version, first.def_version + 1);
    assert!(
        !worker.is_finished(),
        "source response must remain blocked until after management changes"
    );
    release.send(()).unwrap();
    let old = worker
        .await
        .unwrap()
        .expect("in-flight L2 read keeps first grant");
    assert_eq!(
        old.output.rows,
        vec![vec![ontoforge_engine::Value::Long(1)]]
    );
    let denied = L2Service {
        principal: &principal,
        scope: &PrincipalScope::default(),
        active: second.clone(),
        engine: &engine,
        store: &store,
        config: &config,
    }
    .execute_query("SELECT nationkey FROM demo.tiny.nation")
    .await;
    assert!(matches!(denied, Err(L2Error::Denied)));
    let rows = audit_rows(&path, 2).await;
    assert_eq!(rows[0].get::<i64, _>("def_version"), first.def_version);
    assert_eq!(
        rows[0].get::<String, _>("effective_roles"),
        "[\"dispatcher\"]"
    );
    assert_eq!(rows[0].get::<String, _>("status"), "success");
    assert_eq!(rows[1].get::<i64, _>("def_version"), second.def_version);
    assert_eq!(rows[1].get::<String, _>("effective_roles"), "[]");
    assert_eq!(rows[1].get::<String, _>("status"), "denied");
}

async fn audit_pk_denied_before_source_and_source_failure_have_distinct_statuses() {
    let f = fixture(None).await;
    let tokens = TokenCodec::new(b"audit-test-key".to_vec()).unwrap();
    let mut denied_scope = f.scope.clone();
    denied_scope.types.remove(&name("Flight"));
    let denied = QueryService {
        principal: &f.principal,
        scope: &denied_scope,
        active: Arc::clone(&f.active),
        engine: &NeverEngine,
        store: &f.store,
        limits: ExecutionLimits::phase4_default(),
        tokens: &tokens,
    }
    .execute(request("Flight", "F-1001", "status"))
    .await
    .unwrap_err();
    assert!(matches!(denied, QueryError::NotFound));
    let engine = ErrorEngine(AtomicUsize::new(0));
    let source_error = QueryService {
        principal: &f.principal,
        scope: &f.scope,
        active: Arc::clone(&f.active),
        engine: &engine,
        store: &f.store,
        limits: ExecutionLimits::phase4_default(),
        tokens: &tokens,
    }
    .execute(request("Flight", "F-1001", "status"))
    .await
    .unwrap_err();
    assert!(matches!(source_error, QueryError::Source));
    assert_eq!(engine.0.load(Ordering::SeqCst), 1);
    let rows = audit_rows(&f.path, 2).await;
    assert_eq!(
        rows.iter()
            .map(|r| r.get::<String, _>("status"))
            .collect::<Vec<_>>(),
        ["denied", "source_error"]
    );
    assert_eq!(rows[0].get::<String, _>("sql_sha256"), "no-sql");
    let hash = rows[1].get::<String, _>("sql_sha256");
    assert_eq!(hash.len(), 64, "source SQL must be hashed before execution");
    for row in &rows {
        assert_eq!(row.get::<i64, _>("row_count"), 0);
        assert_eq!(row.get::<i64, _>("def_version"), f.active.def_version);
    }
    let db_text = std::fs::read(&f.path).unwrap();
    let db_text = String::from_utf8_lossy(&db_text);
    for secret in [
        "hidden_sql_secret",
        "hidden_result_secret",
        "SELECT ",
        "F-1001",
    ] {
        assert!(!db_text.contains(secret), "audit store leaked {secret}");
    }
}

async fn audit_pk_cancelled_in_flight_records_without_result() {
    let f = Arc::new(
