    tokio::time::timeout(std::time::Duration::from_secs(4), retry)
        .await
        .expect("bounded retry")
        .expect("retry drains accepted guard");
    assert_audit_principal(h, "cancelled").await;
    audit.shutdown().await.expect("repeat successful drain");
}

async fn monitor_startup_owns_fresh_probe_limits_and_cleanup() {
    let (server, fixture) = fixture().await;
    let (l2, ontology) = engines(&server.uri(), Some(PROBE));
    let monitor = l2
        .clone()
        .start_l2_acl_monitor(ontology)
        .await
        .expect("monitor");
    assert_eq!(l2.l2_status(), Some(L2HealthStatus::Enabled));
