async fn monitor_restart_must_clean_previous_generation_before_enabling() {
    let (server, fixture) = fixture().await;
    fixture.cancel_status.store(500, Ordering::SeqCst);
    let (l2, ontology) = engines(&server.uri(), Some(PROBE));
    let first = l2
        .clone()
        .start_l2_acl_monitor(ontology.clone())
        .await
        .expect("first");
    assert_eq!(fixture.submissions.load(Ordering::SeqCst), 1);
    drop(first);
    *fixture.cancel_blocked_id.lock().expect("blocked ID") = Some("active_1".to_owned());
    fixture.cancel_status.store(0, Ordering::SeqCst);
    let second = l2
        .clone()
        .start_l2_acl_monitor_with_options(ontology, options())
        .await
        .expect("second");
    assert_eq!(
        l2.l2_status(),
        Some(L2HealthStatus::Disabled {
            reason: L2DisableReason::CleanupFailed
        }),
        "new generation must not forget the previous live probe"
    );
    assert_eq!(
        fixture.submissions.load(Ordering::SeqCst),
        1,
        "no new probe before prior cleanup"
    );
    *fixture.cancel_blocked_id.lock().expect("blocked ID") = None;
    wait_status(&l2, L2HealthStatus::Enabled).await;
    assert!(fixture.queries.lock().expect("queries").is_empty());
    second.shutdown().await.expect("shutdown");
}

pub async fn audit_shutdown_failure_is_sticky(h: &Harness) {
    let audit = h.store().read_audit();
    reject_audit_insert(h, &h.sys_table("of_read_audit")).await;
    audit
        .reserve(audit_metadata("rejected"))
        .expect("reserve")
        .finish(ReadAuditStatus::Denied, 1)
        .expect("enqueue");
    let first = tokio::time::timeout(std::time::Duration::from_secs(4), audit.shutdown())
        .await
        .expect("bounded failed drain");
    assert_eq!(first, Err(AuditUnavailable));
    assert_eq!(
        audit.shutdown().await,
        Err(AuditUnavailable),
        "repeat shutdown must preserve the worker failure"
    );
    assert!(
        h.rows(Tables::Sys, "of_read_audit", &["principal"], None)
            .await
            .is_empty()
    );
}

async fn audit_shutdown_join_error_is_sticky() {
        let pool = SqlitePool::connect_lazy("sqlite::memory:").expect("lazy pool");
        let audit = ReadAudit::start(&Db::Sqlite(pool), ReadAuditSettings::default());
        {
            let worker = audit.worker.lock().await;
            let Worker::Running(handle) = &*worker else {
                panic!("worker already finished");
            };
            handle.abort();
        }
        assert_eq!(audit.shutdown().await, Err(AuditUnavailable));
        assert_eq!(
            audit.shutdown().await,
            Err(AuditUnavailable),
            "repeat shutdown must preserve the worker join failure"
        );
    }
}

fn dev_distributed_binary_query_action_history_without_checkout() {
    let parent = tempfile::tempdir().expect("temp parent");
    let isolated = parent.path().join("bin");
    fs::create_dir_all(&isolated).expect("isolated dir");
    let copied = isolated.join("ontoforge.exe");
    fs::copy(binary(), &copied).expect("copy binary");
    let mut child = Command::new(&copied)
        .current_dir(&isolated)
        .args(["serve", "--dev", "--bind", &format!("127.0.0.1:{}", port())])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn copied binary");
    std::thread::sleep(Duration::from_secs(2));
    assert!(child.try_wait().expect("child status").is_none());
    child.kill().expect("stop copied binary");
    let _ = child.wait();
    assert!(isolated.join(".ontoforge/dev/server.toml").exists());
}

